layerEngine.themeCss:
body {
  --sanbao-bg: var(--sanbao-canvas);
  --sanbao-surface: var(--sanbao-panel);
  --sanbao-surface2: var(--sanbao-inset);
  --sanbao-ink: var(--sanbao-foreground);
  --sanbao-muted: var(--sanbao-secondary);
  --sanbao-line: var(--sanbao-border);
  --sanbao-good: var(--sanbao-success);
  --sanbao-metal-ink: var(--sanbao-foreground);
  --sanbao-metal-border: var(--sanbao-border);
  --sanbao-metal-fill: var(--sanbao-panel);
  --sanbao-metal-line: var(--sanbao-border);
  --sanbao-metal-highlight: var(--sanbao-hover);
  --sanbao-metal-pressed: var(--sanbao-pressed);
  --sanbao-radius: var(--lute-radius-row, 8px);
  --sanbao-metal-shadow: transparent;
  --sanbao-success-surface: color-mix(in srgb, var(--sanbao-success) 10%, var(--sanbao-canvas));
  --sanbao-warning-surface: color-mix(in srgb, var(--sanbao-warning) 10%, var(--sanbao-canvas));
  --sanbao-error-surface: color-mix(in srgb, var(--sanbao-error) 10%, var(--sanbao-canvas));
  --sanbao-fast: 160ms;
  --sanbao-base: 260ms;
  --sanbao-slow: 520ms;
  --sanbao-ease: cubic-bezier(.22,1,.36,1);
}
